CREATE TABLE IF NOT EXISTS "auctioneer_settings" ("auction_id" integer PRIMARY KEY REFERENCES "auction_listings"("id") ON DELETE CASCADE,"merchant_id" integer NOT NULL REFERENCES "merchants"("id") ON DELETE CASCADE,"enabled" boolean NOT NULL DEFAULT false,"strategy" text NOT NULL DEFAULT 'balanced' CHECK ("strategy" IN ('balanced','premium','competitive','urgency')),"minimum_target_minor" bigint CHECK ("minimum_target_minor" IS NULL OR "minimum_target_minor" >= 0),"maximum_discount_bps" integer NOT NULL DEFAULT 0 CHECK ("maximum_discount_bps" BETWEEN 0 AND 5000),"max_extension_minutes" integer NOT NULL DEFAULT 0 CHECK ("max_extension_minutes" BETWEEN 0 AND 1440),"daily_action_limit" integer NOT NULL DEFAULT 20 CHECK ("daily_action_limit" BETWEEN 0 AND 500),"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "auctioneer_actions" ("id" bigserial PRIMARY KEY,"auction_id" integer NOT NULL REFERENCES "auction_listings"("id") ON DELETE RESTRICT,"merchant_id" integer NOT NULL REFERENCES "merchants"("id") ON DELETE RESTRICT,"action_type" text NOT NULL,"status" text NOT NULL DEFAULT 'planned',"idempotency_key" text NOT NULL UNIQUE,"recommendation" jsonb NOT NULL DEFAULT '{}'::jsonb,"evidence" jsonb NOT NULL DEFAULT '{}'::jsonb,"created_at" timestamptz NOT NULL DEFAULT now(),"executed_at" timestamptz); CREATE INDEX IF NOT EXISTS "auctioneer_actions_auction_idx" ON "auctioneer_actions" ("auction_id","created_at" DESC);
CREATE TABLE IF NOT EXISTS "lunavo_transaction_control" ("id" bigserial PRIMARY KEY,"merchant_id" integer REFERENCES "merchants"("id") ON DELETE SET NULL,"transaction_kind" text NOT NULL,"reference_key" text NOT NULL UNIQUE,"provider" text,"provider_reference" text,"amount_minor" bigint NOT NULL CHECK ("amount_minor" >= 0),"currency" text NOT NULL CHECK ("currency" = upper("currency") AND char_length("currency") = 3),"status" text NOT NULL DEFAULT 'initiated',"dashboard_visible" boolean NOT NULL DEFAULT true,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now()); CREATE UNIQUE INDEX IF NOT EXISTS "lunavo_transaction_control_provider_ref_idx" ON "lunavo_transaction_control" ("provider","provider_reference") WHERE "provider" IS NOT NULL AND "provider_reference" IS NOT NULL; CREATE INDEX IF NOT EXISTS "lunavo_transaction_control_merchant_idx" ON "lunavo_transaction_control" ("merchant_id","created_at" DESC);